INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (17, 8, 'theory', 'Quiz: KVM, QEMU and libvirt');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 8, 0, 'What does the KVM module do?', '["Emulates the guest''s devices", "Turns the Linux kernel into a hypervisor: guests run directly on the processor", "Manages the host''s network", "Encrypts disk images"]', 1, 'KVM provides the /dev/kvm interface and entry into the guest; devices and the machine model are left to QEMU.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 8, 1, 'How are virtual processors scheduled in KVM?', '["By the hypervisor''s own scheduler", "By the guest''s scheduler", "By the Linux scheduler: each vCPU is an ordinary thread of the QEMU process", "Only manually by the administrator"]', 2, 'That is why top, control groups and core pinning work on the host.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 8, 2, 'Why does the kernel itself emulate some devices, such as the interrupt controller and timers?', '["To avoid exiting to QEMU on every frequent event", "To save disk space", "Because of licenses", "So that QEMU need not be started"]', 0, 'Whatever happens often and is simple is moved closer to the kernel; the rare and complex stays in QEMU.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 8, 3, 'Why is QEMU considered the main attack surface of the hypervisor?', '["It cannot encrypt", "It uses the network", "It always runs as the superuser with no restrictions", "It is large, written in C and emulates hundreds of devices: a bug in a device can become an escape from the guest"]', 3, 'That is why it is run as an unprivileged user and restricted with seccomp, SELinux or AppArmor, and cgroups.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 8, 4, 'What role does libvirt play?', '["Emulates the processor", "A management layer: describes machines in XML, launches QEMU and controls it", "Replaces the Linux kernel", "Stores disk images"]', 1, 'Cloud platforms such as OpenStack manage servers precisely through libvirt.');
